// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 burnWords) public {
        amount = bound(amount, 0, 1e20);
        burnWords = bound(burnWords, 0, 5000);

        GasBurner helper = new GasBurner(burnWords);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract GasBurner {
    uint256 public wordsToBurn;
    constructor(uint256 _words) payable {
        wordsToBurn = _words;
    }
    receive() external payable {
        uint256 i = 0;
        while (i < wordsToBurn) {
            assembly { mstore(0x0, i) }
            i++;
        }
    }
}
